#include "layer_panel_tree.h"
#include "editor_timeline_rows.h"
#include <iostream>
#include <stdexcept>
using namespace moon;
static void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);}
int main(){try{
 {
 timeline::State state;for(const char* id:{"top","middle","bottom"}){timeline::Layer l;l.id=id;state.layers.push_back(l);}state.layers[0].groupId="a";state.layers[2].groupId="b";timeline::Group a;a.id="a";a.panelOrder=2;timeline::Group b;b.id="b";b.panelOrder=0;state.groups={a,b};state.frames={{"f0",100,false},{"f1",100,false}};for(const auto& l:state.layers)for(const auto& f:state.frames){timeline::Cel c;c.id=l.id+"/"+f.id;c.layerId=l.id;c.frameId=f.id;state.cels.push_back(c);}
 state.groups[0].displayColor=0xff123456;state.groups[1].parentGroupId="a";state.layers[2].groupId="b";
 editor::TimelineRows nested(state,{});check(nested.ancestorColors(nested.index("bottom"))==std::vector<std::optional<timeline::Pixel>>{0xff123456,std::nullopt},"Every nested level retains outer-to-inner color strip, including no color");check(nested.ancestorColors(nested.index("b"))==std::vector<std::optional<timeline::Pixel>>{0xff123456},"Nested group uses parent strip, not its own color");
 state.groups[0].displayColor.reset();state.groups[1].parentGroupId.reset();
 editor::TimelineRows rows(state,{});check(rows.size()==5&&rows.index("a")==0&&rows.index("top")==1&&rows.index("middle")==2&&rows.index("b")==3&&rows.index("bottom")==4,"Visible row identity includes ordinary groups");check(!rows.layerIndex(0)&&!rows.cel(0,0)&&rows.cel(1,0)->id=="top/f0"&&rows.layerIndex(2)==std::optional<std::size_t>(1),"Group row is never raw layer/cel index");auto range=rows.rectangle(0,0,2,1);check(range.size()==6&&range[0]==editor::TimelineSlot{"a","f0"}&&range[5]==editor::TimelineSlot{"middle","f1"},"Visual rectangle retains group decoration separately");
 const auto anchor=rows.mixedAnchor({"a","f0"},{"middle/f0","top/f0"});check(anchor&&anchor->id=="top/f0","Mixed group grab uses nearest selected real same-frame cel");check(!rows.mixedAnchor({"a","f1"},{"top/f0"}),"Virtual group slot does not invent a content anchor");auto target=rows.mixedTarget(*anchor,{"a","f0"},3,1);check(target&&target->id=="bottom/f1","Mixed visual pointer resolves nearest real row");auto groups=rows.movedGroups({{"a","f0"}},*anchor,*target);check(groups==std::vector<editor::TimelineSlot>{{"b","f1"}},"Virtual decoration translates only onto group destination");editor::TimelineRows collapsed(state,{"a"});check(collapsed.index("top")==-1&&collapsed.size()==4&&!collapsed.cel(0,0)&&collapsed.cel(1,0)->id=="middle/f0","Collapse keeps identity without raw index aliasing");auto flat=state;flat.groups.clear();for(auto& l:flat.layers)l.groupId.reset();editor::TimelineRows noGroups(flat,{});check(noGroups.size()==3&&noGroups.cel(0,0)->id=="top/f0"&&noGroups.cel(2,1)->id=="bottom/f1","No-group frame cells preserve top-first order");
 }

 const auto L=LayerPanelKind::Layer,G=LayerPanelKind::Group;
 std::vector<LayerPanelLayerRef> layers{{"background",{}},{"body","characters"},{"eyes","characters"},{"highlight","face"}};
 std::vector<LayerPanelGroupRef> groups{{"characters",{},{}},{"face","characters",{}}};
 const std::vector<LayerPanelNode> expected{{G,"characters",0},{G,"face",1},{L,"highlight",2},{L,"eyes",1},{L,"body",1},{L,"background",0}};
 check(buildLayerPanelTree(layers,groups)==expected,"Legacy nested group display order");
 check(buildLayerPanelTree(layers,groups,{"characters"})==std::vector<LayerPanelNode>{{G,"characters",0},{L,"background",0}},"Collapsed group hides descendants");
 check(buildLayerPanelTree(std::vector<LayerPanelLayerRef>{{"background",{}}},{{"older",{},{}},{"newer",{},{}}})==std::vector<LayerPanelNode>{{G,"newer",0},{G,"older",0},{L,"background",0}},"Empty groups stay above container layers");
 check(buildLayerPanelTree(std::vector<LayerPanelLayerRef>{{"bottom",{}},{"member","moved"},{"top",{}}},{{"moved",{},.25}})==std::vector<LayerPanelNode>{{L,"top",0},{G,"moved",0},{L,"member",1},{L,"bottom",0}},"Persisted anchor orders nonempty group");
 check(layerPanelAncestorGroupIds(groups,"face")==std::vector<std::string>{"face","characters"},"Immediate-to-root ancestors");check(layerPanelDescendantGroupIds(groups,"characters")==std::vector<std::string>{"face"},"Breadth-first descendants");
 check(layerPanelAncestorGroupIds({{"first","second",{}},{"second","first",{}}},"first")==std::vector<std::string>{"first","second"},"Damaged ancestor cycle terminates");
 auto topFirst=std::vector<LayerPanelLayerRef>(layers.rbegin(),layers.rend());check(buildLayerPanelTreeFromTopFirst(topFirst,groups)==expected,"Native top-first adapter preserves legacy anchors/order");check(buildLayerPanelTreeFromTopFirst({{"top",{}},{"bottom",{}}},{})==std::vector<LayerPanelNode>{{L,"top",0},{L,"bottom",0}},"Native no-group order preserved by adapter");
 LayerPanelSelection selected;selected.activeLayer="background";selected=selectLayerPanelRow(layers,groups,{},selected,{G,"characters",0});check(selected.groups==std::vector<std::string>{"characters"}&&selected.layers.empty()&&selected.singleGroup==std::optional<std::string>("characters")&&selected.activeLayer=="body","Pure group selection owns row only and resolves first source member");
 auto ranged=selectLayerPanelRow(layers,groups,{},selected,{L,"highlight",2},LayerPanelSelectionMode::Range);check(ranged.groups==std::vector<std::string>({"characters","face"})&&ranged.layers==std::vector<std::string>({"highlight","eyes","body"})&&!ranged.singleGroup&&ranged.anchor==selected.anchor,"Shift group-to-child spans full visible subtree");
 auto mixed=selectLayerPanelRow(layers,groups,{},selected,{L,"background",0},LayerPanelSelectionMode::Toggle);check(mixed.groups==std::vector<std::string>{"characters"}&&mixed.layers==std::vector<std::string>{"background"}&&!mixed.singleGroup,"Mixed group/layer selection retains explicit layer ids");
 auto removed=selectLayerPanelRow(layers,groups,{},mixed,{G,"characters",0},LayerPanelSelectionMode::Toggle);check(removed.groups.empty()&&removed.layers==std::vector<std::string>{"background"},"Toggle group leaves independent layer selected");auto collapsed=toggleLayerPanelGroupCollapsed({},"characters");check(collapsed==std::vector<std::string>{"characters"}&&toggleLayerPanelGroupCollapsed(collapsed,"characters").empty(),"Expand/collapse independent UI state");
 auto across=selectLayerPanelRow(layers,groups,collapsed,selected,{L,"background",0},LayerPanelSelectionMode::Range);check(across.groups==std::vector<std::string>{"characters"}&&across.layers==std::vector<std::string>{"background"},"Collapsed range excludes hidden children");std::cout<<"Layer panel tree tests passed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
